<script lang="ts">
 import {onMount} from 'svelte';
 let data=$state<any>(),bundle=$state<any>(),runtime=$state<any>(),error=$state(''),busy=$state(false),filter=$state(''),category=$state('all'),sort=$state('new'),native=$state('未檢查'),after=$state(''),before=$state('');
 const within=(n:number|undefined)=>(!after&&!before)||!!n&&(!after||n>=new Date(after+'T00:00:00').getTime())&&(!before||n<=new Date(before+'T23:59:59.999').getTime());
 const size=(n:number|undefined)=>n===undefined?'尚未計量':n<1048576?`${(n/1024).toFixed(1)} KiB`:`${(n/1048576).toFixed(2)} MiB`;
 const date=(n:number|undefined)=>n?new Date(n).toLocaleString('zh-TW'):'未記錄';
 async function call(channel:string,extra:object={}){const result=await chrome.runtime.sendMessage({channel,...extra});if(!result?.ok)throw new Error(result?.error??'管理頁未回應');return result;}
 async function refresh(){busy=true;error='';try{const r=await call('cache-inventory');data={...r.result,inUse:r.busy};runtime=(await call('runtime-status')).result;bundle=await fetch(chrome.runtime.getURL('/bundle-inventory.json')).then(r=>r.ok?r.json():undefined);}catch(e){error=String(e);}finally{busy=false;}}
 async function scan(){busy=true;error='';try{data=(await call('cache-scan')).result;}catch(e){error=String(e);}finally{busy=false;}}
 async function remove(selection:object){if(!confirm('刪除選取快取？頁面原文、譯文與人工校正將從快取移除；套件內資源不受影響。'))return;busy=true;error='';try{data=(await call('cache-remove',{selection})).result;}catch(e){error=String(e);}finally{busy=false;}}
 async function release(){try{const r=await call('runtime-release');error=r.busy?'正在等待在途任務完成，完成後釋放。':'';await refresh();}catch(e){error=String(e);}}
 async function checkNative(){try{const {chromeTranslatorAvailability}=await import('./chrome-translator');const r=await chromeTranslatorAvailability();native=r.status+' · 大小由 Chrome 管理，未提供';}catch(e){error=String(e);}}
 onMount(()=>{void refresh();});
 const phase:Record<string,string>={loading:'載入中',unloaded:'未載入',released:'已釋放',running:'執行中',waiting:'待釋放'};
 const rows=$derived((data?.pages??[]).filter((p:any)=>[p.title,p.chapter,p.source,p.backend,p.hash].some(v=>String(v??'').includes(filter))&&within(p.savedAt)).sort((a:any,b:any)=>sort==='size'?b.bytes-a.bytes:sort==='old'?(a.savedAt??0)-(b.savedAt??0):(b.savedAt??0)-(a.savedAt??0)));
</script>
<main><a href="options.html">← 模型與閱讀設定</a><h1>快取與推論資源</h1><p>磁碟內容、Chrome 儲存估算與模型記憶體分開顯示。</p>
<div class="actions"><button disabled={busy} onclick={refresh}>重新計量</button><button disabled={busy||data?.inUse} onclick={scan}>串流掃描模型大小</button><button disabled={busy} onclick={release}>釋放閒置模型</button></div>
{#if error}<p role="alert">{error}</p>{/if}{#if busy}<p role="status">讀取中…</p>{/if}
<section><h2>推論狀態：{phase[runtime?.phase]??'讀取中'}</h2><p>模型會在全部分頁閒置 60 秒後釋放；已顯示譯圖仍保留。外部本機服務由使用者管理。</p>{#if runtime?.worker}<p>模型：{runtime.models??0} · WASM 設定：{runtime.threads??'未初始化'} · 實際 pthread：{runtime.spawnedPthreads??0} · 隔離：{String(runtime.crossOriginIsolated)}</p>{#if runtime.reason}<p>{runtime.reason}</p>{/if}{/if}{#if runtime?.translatorLoaded}<p>Chrome Translator 會話：已載入</p>{/if}</section>
{#if data}<section><h2>內容大小</h2><p>頁面文字與校正：{size(data.pageBytes)}（{data.pages.length} 份，上限 30 份）</p><p>已計量下載模型：{size(data.modelBytes)} · 尚待掃描 {data.unmeasured} 項</p><p>Chrome origin 儲存用量估算：{size(data.estimate?.usage)}；此為瀏覽器估算，不與上述內容大小直接相加。</p></section>{/if}
<label>顯示類型 <select bind:value={category}><option value="all">全部</option><option value="pages">頁面文字</option><option value="models">下載模型</option><option value="bundle">套件資源</option></select></label>
<div><input aria-label="篩選快取來源" bind:value={filter} placeholder="作品、網址、來源或圖片雜湊"><select aria-label="快取排序" bind:value={sort}><option value="new">最新保存</option><option value="old">最早保存</option><option value="size">大小</option></select><label>起日 <input type="date" bind:value={after}></label><label>迄日 <input type="date" bind:value={before}></label></div>
{#if data&&(category==='all'||category==='pages')}<section><h2>頁面文字與校正</h2><button disabled={busy||data.inUse} onclick={()=>remove({kind:'pages'})}>清除全部頁面文字</button><table><thead><tr><th>頁面／來源</th><th>區域</th><th>保存時間</th><th>內容大小</th><th>操作</th></tr></thead><tbody>{#each rows as p}<tr><td>{p.title||p.hash?.slice(0,12)||'未命名'} {p.chapter} {p.pageIndex===undefined?'':`第 ${p.pageIndex+1} 張`}<small>{p.backend} · {p.source||'來源未記錄'}</small></td><td>{p.regions}</td><td>{date(p.savedAt)}</td><td>{size(p.bytes)}</td><td><button disabled={busy||data.inUse} onclick={()=>remove({kind:'page',key:p.key})}>刪除</button></td></tr>{/each}</tbody></table></section>{/if}
{#if data&&(category==='all'||category==='models')}<section><h2>下載模型</h2><button disabled={busy||data.inUse} onclick={()=>remove({kind:'models'})}>清除下載模型</button>{#each data.models.filter((m:any)=>[m.id,m.url,m.cache].some(v=>String(v).includes(filter))&&within(m.measuredAt)).sort((a:any,b:any)=>sort==='size'?(b.bytes??0)-(a.bytes??0):sort==='old'?(a.measuredAt??0)-(b.measuredAt??0):(b.measuredAt??0)-(a.measuredAt??0)) as m}<article><strong>{m.id} · {m.url.split('/').at(-1)}</strong><small>{m.cache} · {m.version} · {m.url}</small><p>群組已存 {data.models.filter((row:any)=>row.id===m.id).length}/{m.expected??'總數未記錄'} 檔 · {size(m.bytes)} · 計量：{date(m.measuredAt)} · {m.verified?'已驗證雜湊':'完整性未記錄'}</p><button disabled={busy||data.inUse} onclick={()=>remove({kind:'model',cache:m.cache,url:m.url})}>刪除此檔</button><button disabled={busy||data.inUse} onclick={()=>remove({kind:'model-group',group:m.id})}>刪除此模型群組</button></article>{/each}</section>{/if}
{#if category==='all'||category==='bundle'}<section><h2>套件內建資源</h2><p>隨擴充套件安裝；清除下載快取不會移除此類檔案。</p>{#each bundle?.groups??[] as group}<p>{group.name} · {group.files} 個檔案 · {size(group.bytes)}</p>{/each}</section>{/if}
<section><h2>Chrome 翻譯語言包</h2><button onclick={checkNative}>檢查語言包狀態</button><p>{native}</p></section>
</main><style>:global(body){margin:0;background:#f1eee6;color:#293f32;font:14px system-ui}main{max-width:1100px;margin:auto;padding:28px}section{background:#fafbf7;border:1px solid #ccd5c7;border-radius:10px;margin:18px 0;padding:20px}button,input,select{font:inherit;padding:8px;margin:5px;border:1px solid #afc1b1;border-radius:6px;background:white;color:#284e3c}button{cursor:pointer}button:disabled{opacity:.5}small{display:block;overflow-wrap:anywhere;color:#66776c}table{border-collapse:collapse;width:100%;margin-top:14px}td,th{text-align:left;border-bottom:1px solid #ddd;padding:10px}article{border-bottom:1px solid #ddd;padding:12px 0}[role=alert]{color:#963d2a}.actions{display:flex;flex-wrap:wrap}</style>
